import { useState } from "react";
import React from "react";
import AddTaskModal from "./AddTaskModal";
import EditTaskModal from "./EditTaskModal";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskListProps{
    tasks: Task[];
    markTaskAsDone: (id: number) => void;
    onTaskAdded: () => void;
    onTaskUpdated: () => void;
}

const TaskList: React.FC<TaskListProps> = ({ tasks, markTaskAsDone, onTaskAdded, onTaskUpdated }) => {
    const [showAddModal, setShowAddModal] = useState(false);

    {showAddModal && <AddTaskModal onClose={() => setShowAddModal(false)} onTaskAdded={onTaskAdded} />}



    return(
        <div>
            <button onClick={() => setShowAddModal(true)}>New Task</button>

            {showAddModal && <AddTaskModal onClose={() => setShowAddModal(false)} onTaskAdded={onTaskAdded} />}

            {taskToEdit && (
                <EditTaskModal
                    task = {taskToEdit}
                    onClose = {() => setTaskToEdit(null)}
                    onTaskUpdated = {onTaskUpdated}
                />
            )}

            <h2>Task List</h2>

            {tasks.length === 0 ? (
                <p>No available tasks!</p>
            ) : (
                <ul>
                    {tasks.map((task) => (
                        <li key={task.id}>

                            <input
                                type = "checkbox"
                                checked = {task.doneFlag}
                                onChange = {() => markTaskAsDone(task.id)}
                            />

                            <strong style = {{ textDecoration: task.doneFlag ? "line-through" : "none" }}>
                                {task.text}
                            </strong>
                            {" - "}
                            {task.priority}

                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default TaskList;
